// ============================================================================
// GDDR7_Lite_apb: APB4 register wrapper around GDDR7_Lite_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/GDDR7_Lite.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/GDDR7_Lite.md
// ============================================================================
module GDDR7_Lite_apb #(
  parameter integer T_RCD = 6,
  parameter integer T_RP = 6,
  parameter integer T_RC = 24,
  parameter integer T_RAS = 16,
  parameter integer T_RRD = 3,
  parameter integer T_WR = 8,
  parameter integer T_WTR = 4,
  parameter integer T_RFC = 40,
  parameter integer T_REFI = 3900,
  parameter integer CL = 11,
  parameter integer CWL = 8
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic pam3,
  output logic ck_t,
  output logic ck_c,
  output logic cke,
  output logic cs_n,
  output logic act_n,
  output logic ras_n,
  output logic cas_n,
  output logic we_n,
  output logic [1:0] ba,
  output logic [13:0] addr,
  inout tri [31:0] dq,
  inout tri [1:0] dqs,
  output logic trace_valid,
  output logic [3:0] trace_cmd,
  output logic [31:0] trace_addr
);
  localparam logic [31:0] ID_VALUE = 32'h6D220200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [13:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd14) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_hvalid;
  logic          c_hready;
  logic [2:0]    c_hcmd;
  logic [31:0]   c_haddr;
  logic [15:0]   c_hwdata;
  logic [15:0]   c_hrdata;
  logic [127:0]  c_rdline;
  logic          c_hdone;
  logic          c_irq;
  logic          c_pam3;
  GDDR7_Lite_top #(.T_RCD(T_RCD), .T_RP(T_RP), .T_RC(T_RC), .T_RAS(T_RAS), .T_RRD(T_RRD), .T_WR(T_WR), .T_WTR(T_WTR), .T_RFC(T_RFC), .T_REFI(T_REFI), .CL(CL), .CWL(CWL)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .hvalid(c_hvalid),
    .hready(c_hready),
    .hcmd(c_hcmd),
    .haddr(c_haddr),
    .hwdata(c_hwdata),
    .hrdata(c_hrdata),
    .rdline(c_rdline),
    .hdone(c_hdone),
    .irq(c_irq),
    .pam3(c_pam3),
    .ck_t(ck_t),
    .ck_c(ck_c),
    .cke(cke),
    .cs_n(cs_n),
    .act_n(act_n),
    .ras_n(ras_n),
    .cas_n(cas_n),
    .we_n(we_n),
    .ba(ba),
    .addr(addr),
    .dq(dq),
    .dqs(dqs),
    .trace_valid(trace_valid),
    .trace_cmd(trace_cmd),
    .trace_addr(trace_addr)
  );
  assign pam3 = c_pam3;  // also readable in the registers

  // ---------------- registers ----------------
  logic [3:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [2:0] h_CMD0;   // 12'h014 CMD0 holding register
  logic [31:0] h_CMD1;   // 12'h018 CMD1 holding register
  logic [15:0] h_CMD2;   // 12'h01C CMD2 holding register
  logic full_CMD;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      h_CMD0 <= '0;
      h_CMD1 <= '0;
      h_CMD2 <= '0;
      full_CMD <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[3:0] & wmask[3:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5] && !full_CMD) h_CMD0 <= (h_CMD0 & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[6] && !full_CMD) h_CMD1 <= (h_CMD1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7] && !full_CMD) h_CMD2 <= (h_CMD2 & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[7] && !full_CMD) full_CMD <= 1'b1;
      else if (full_CMD && c_hready) full_CMD <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_hcmd[2:0] = h_CMD0[2:0];
  assign c_haddr[31:0] = h_CMD1[31:0];
  assign c_hwdata[15:0] = h_CMD2[15:0];
  assign c_hvalid = full_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_hdone;
    irq_set[1] = c_irq;
    irq_set[2] = full_CMD & c_hready;
    irq_set[3] = wr & (hit[5] | hit[6] | hit[7]) & full_CMD;
  end
  assign irq = |(irq_status & irq_enable);
  wire [0:0] flags = {full_CMD};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(h_CMD0);
      10'd6: apb_rdata = 32'(h_CMD1);
      10'd7: apb_rdata = 32'(h_CMD2);
      10'd8: apb_rdata = 32'({c_hrdata});
      10'd9: apb_rdata = 32'({c_rdline[31:0]});
      10'd10: apb_rdata = 32'({c_rdline[63:32]});
      10'd11: apb_rdata = 32'({c_rdline[95:64]});
      10'd12: apb_rdata = 32'({c_rdline[127:96]});
      10'd13: apb_rdata = 32'({c_pam3});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
